            if strings.HasSuffix(line, suffix) { ignored = true; break }
        }
        if ignored { continue }
        owner, err := o.parseInstalledPackagesLine(line)
        if err != nil { return nil, xerrors.Errorf("Failed to parse rpm -qf line %q: %w", line, err) }
        owners = append(owners, owner)
    }
    if err := scanner.Err(); err != nil { return nil, err }
    return owners, nil
}

